#if DEBUG
import Foundation

/// Synthetic, fully fictional data for CI screenshots of the 0.5 feature screens (a product studio
/// talking to an invented fitness-app brand; every name, quote and number is made up). Compiled only
/// in Debug; the Release IPA has no sample data. Stores read these directly in preview mode, so a screen works
/// even before PreviewFixtures merges `stateFields(for:)` into its TrainingState fixture.
@MainActor enum FeaturePreviewFixtures {
    /// `--preview=<name>` screens owned by the feature screens.
    static let screens = ["placement-intro", "placement-listening", "placement-reading", "placement-break",
                          "placement-speaking", "placement-roleplay", "placement-scoring", "placement-result",
                          "calls", "call-review", "call-transcript", "call-speakers", "patterns", "facts"]

    static func isPlacementScreen(_ screen: String?) -> Bool { (screen ?? "").hasPrefix("placement-") }
    static func isCallsScreen(_ screen: String?) -> Bool {
        ["calls", "call-review", "call-transcript", "call-speakers", "patterns", "facts"].contains(screen ?? "")
            || PrepPreview.callsScreens.contains(screen ?? "")
    }

    /// Canned API responses by request path (for TrainingClient.previewResponses).
    static func response(for path: String) -> Data? {
        switch path {
        case "placement": return Data(placement_result.utf8)
        case "calls": return Data(callsList.utf8)
        case "patterns": return Data(patternsList.utf8)
        case "facts": return Data(factsList.utf8)
        case "calls/call-pulse": return Data(detailReady.utf8)
        case "calls/call-harbor": return Data(detailSpeakers.utf8)
        case "calls/call-northwind": return Data(detailProcessing.utf8)
        default: return nil
        }
    }

    /// Request paths answered by `response(for:)`.
    static let responsePaths = ["placement", "calls", "patterns", "facts", "calls/call-pulse", "calls/call-harbor", "calls/call-northwind"]

    static func placementView(for screen: String?) -> PlacementView? {
        guard let json = placementJSON(for: screen) else { return nil }
        return decode(json)
    }

    static func calls(for screen: String?) -> [CallSummary]? {
        guard isCallsScreen(screen) else { return nil }
        let envelope: CallsEnvelope? = decode(callsList)
        return envelope?.calls
    }

    static func callDetails(for screen: String?) -> [String: CallDetail] {
        guard isCallsScreen(screen) else { return [:] }
        var result: [String: CallDetail] = [:]
        for json in [detailReady, detailSpeakers, detailProcessing] {
            if let detail: CallDetail = decode(json) { result[detail.id] = detail }
        }
        return result
    }

    static func patterns(for screen: String?) -> [CommunicationPattern]? {
        guard isCallsScreen(screen) else { return nil }
        let envelope: PatternsEnvelope? = decode(patternsList)
        return envelope?.patterns
    }

    static func facts(for screen: String?) -> [ProfileFact]? {
        guard isCallsScreen(screen) else { return nil }
        let envelope: FactsEnvelope? = decode(factsList)
        return envelope?.profileFacts
    }

    static func drills(for screen: String?) -> [PersonalDrill]? {
        guard isCallsScreen(screen) else { return nil }
        let list: LossyArray<PersonalDrill>? = decode(drillsList)
        return list?.elements
    }

    /// Where CallsScreen navigates on launch for a preview screen.
    static func initialRoute(for screen: String?) -> CallsRoute? {
        switch screen ?? "" {
        case "call-review", "call-transcript": return .call("call-pulse")
        case "call-speakers": return .call("call-harbor")
        case "patterns": return .patterns
        case "facts": return .facts
        default: return PrepPreview.initialRoute(screen)
        }
    }

    static func initialCallTab(for screen: String?) -> CallDetailTab? {
        screen == "call-transcript" ? .transcript : nil
    }

    /// JSON values to merge into PreviewFixtures' TrainingState dictionary:
    /// placement, calls, patterns, drills, profileFacts.
    static func stateFields(for screen: String?) -> [String: Any] {
        var fields: [String: Any] = [:]
        if let value = object(placementJSON(for: screen) ?? placement_result) { fields["placement"] = value }
        if let value = object(callsList) as? [String: Any], let list = value["calls"] { fields["calls"] = list }
        if let value = object(patternsList) as? [String: Any], let list = value["patterns"] { fields["patterns"] = list }
        if let value = object(factsList) as? [String: Any], let list = value["profileFacts"] { fields["profileFacts"] = list }
        if let list = object(drillsList) { fields["drills"] = list }
        return fields
    }

    private static func placementJSON(for screen: String?) -> String? {
        switch screen ?? "" {
        case "placement-intro": return placement_intro
        case "placement-listening": return placement_listening
        case "placement-reading": return placement_reading
        case "placement-break": return placement_break
        case "placement-speaking": return placement_speaking
        case "placement-roleplay": return placement_roleplay
        case "placement-scoring": return placement_scoring
        case "placement-result": return placement_result
        default: return nil
        }
    }

    private static func decode<T: Decodable>(_ json: String) -> T? {
        try? JSONDecoder().decode(T.self, from: Data(json.utf8))
    }

    private static func object(_ json: String) -> Any? {
        try? JSONSerialization.jsonObject(with: Data(json.utf8))
    }

